#!/usr/bin/env node
/**
 * Bavarian State Library / MDZ map harvest — 2026-10-20.
 *
 * Discovery uses the official MDZ catalogue's own JSON search endpoint, the
 * same `/api/search` service the public website calls, restricted to the
 * documented collection facet `Karten und Pläne` / `Maps and Plans` (137).
 * Each catalogue item's `/api/metadata/<id>` record states its item-level
 * licence. Only Public Domain Mark 1.0 (or CC0 1.0) items are admitted; the
 * IIIF Presentation API 2 manifest and Image API 2 service are the documented
 * image routes (see https://www.digitale-sammlungen.de/en/interfaces).
 *
 * The redistributed fields are the factual description of the PDM object plus
 * its URN and record link. MDZ publishes no separate metadata licence; none is
 * asserted. The FAQ's PDM permission is recorded as the rights basis, exactly
 * as for the SLUB PDM scope. In-copyright, NoC and CC BY-NC-SA items are
 * counted and withheld, never relabelled.
 *
 * Records go to their own shard (`/data/records/mdz.json`). No map extent,
 * projection or alignment is inferred from a place or scale string.
 *
 * Usage:
 *   node scripts/harvest-mdz.mjs                 # cached harvest, writes public/data
 *   node scripts/harvest-mdz.mjs --refresh       # refetch search pages and metadata
 *   node scripts/harvest-mdz.mjs --no-write      # report only
 *   node scripts/harvest-mdz.mjs --verify 12     # live sample size
 *   node scripts/harvest-mdz.mjs --concurrency 6
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { publishProviderShard, readCore, shardUrl } from './catalogue.mjs';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const has = (name) => args.includes(`--${name}`);
const value = (name, fallback) => {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = resolve(value('out', resolve(ROOT, 'public/data')));
const CACHE = resolve(ROOT, '.cache/mdz');
const REFRESH = has('refresh');
const WRITE = !has('no-write') && !has('dry-run');
const VERIFY_SAMPLE = Math.max(0, Number(value('verify', '12')) || 0);
const CONCURRENCY = Math.max(1, Math.min(12, Number(value('concurrency', '8')) || 8));
const UA = 'maps-n-stuff/0.2 (+https://github.com/igor-makarov/maps-n-stuff; MDZ map harvest)';
const SEARCH = 'https://www.digitale-sammlungen.de/api/search';
const METADATA = 'https://www.digitale-sammlungen.de/api/metadata';
const MANIFEST = 'https://api.digitale-sammlungen.de/iiif/presentation/v2';
const IMAGE = 'https://api.digitale-sammlungen.de/iiif/image/v2';
const RECORD = 'https://www.digitale-sammlungen.de/en/view';
const SHARD = shardUrl('mdz');
const RETRIEVED = '2026-10-20';
const COLLECTION_ID = '137';
const COLLECTION_NAME = 'Karten und Pläne / Maps and Plans';
const PAGE_SIZE = 100;
const PD_MARK = 'creativecommons.org/publicdomain/mark/1.0';
const CC0 = 'creativecommons.org/publicdomain/zero/1.0';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const decode = (text) =>
  String(text ?? '')
    .replace(/<!\[CDATA\[|\]\]>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;|&apos;/g, "'")
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .trim();
const plain = (text) => decode(String(text ?? '').replace(/<[^>]*>/g, ' ')).replace(/\s+/g, ' ').trim();
const unique = (values) => [...new Set(values.map((value) => plain(value)).filter(Boolean))];

/** All plausible publication years in an MDZ date string (e.g. "ca. 1939-1942"). */
export function publicationYears(text) {
  const years = [...String(text ?? '').matchAll(/\b(1[4-9][0-9]{2}|20[0-9]{2})\b/g)].map((m) => Number(m[1]));
  if (!years.length) return null;
  return { start: Math.min(...years), end: Math.max(...years) };
}

/** Normalise a licence URL so http/https and a trailing slash do not matter. */
export function normaliseLicence(url) {
  return String(url ?? '')
    .trim()
    .replace(/^https?:\/\//i, '')
    .replace(/\/+$/, '')
    .toLowerCase();
}

/** The item-level rights gate: only PDM 1.0 and CC0 1.0 are reusable here. */
export function admitItem(metadata) {
  if (!metadata || !plain(metadata.title)) return { ok: false, reason: 'no-title' };
  if (metadata.iiifAvailable !== true) return { ok: false, reason: 'no-iiif' };
  const licence = normaliseLicence(metadata.license);
  if (licence === PD_MARK) return { ok: true, basis: 'pdm', licence: 'https://creativecommons.org/publicdomain/mark/1.0/' };
  if (licence === CC0) return { ok: true, basis: 'cc0', licence: 'https://creativecommons.org/publicdomain/zero/1.0/' };
  if (!licence) return { ok: false, reason: 'licence:unstated' };
  return { ok: false, reason: `licence:${licence}` };
}

/** Convert an MDZ metadata document plus its search hit into a catalogue record. */
export function mdzRecord(metadata, hit = {}) {
  const gate = admitItem(metadata);
  if (!gate.ok) return { record: null, reason: gate.reason };
  const id = String(metadata.id);
  const previewId = metadata.previewId ?? hit.previewPage;
  const recordUrl = `${RECORD}/${id}`;
  const creators = unique([
    ...(metadata.creators ?? []).map((creator) => creator.name ?? creator),
    ...(metadata.contributors ?? []).map((contributor) => contributor.name ?? contributor),
  ]);
  const languages = unique((metadata.languages ?? []).map((language) => language._raw_ ?? language.de ?? language.en));
  const years = publicationYears(metadata.publishedDate);
  const places = unique(hit.publicationPlaces ?? []);
  const record = {
    id: `mdz:${id}`,
    title: plain(metadata.title),
    creators,
    providerId: 'mdz',
    institution: 'Bayerische Staatsbibliothek (Bavarian State Library)',
    collection: `${COLLECTION_NAME} (Bayerische Staatsbibliothek)`,
    originalCollection: COLLECTION_NAME,
    type: 'map',
    rights:
      gate.basis === 'pdm'
        ? 'Public Domain Mark 1.0 <https://creativecommons.org/publicdomain/mark/1.0/> (item-level MDZ metadata licence).'
        : 'CC0 1.0 <https://creativecommons.org/publicdomain/zero/1.0/> (item-level MDZ metadata licence).',
    rightsBasis: gate.basis,
    rightsUrl: gate.licence,
    rightsPolicyUrl: 'https://www.digitale-sammlungen.de/en/faq',
    rightsNote:
      'The MDZ item metadata states this licence. The MDZ FAQ states that digital copies provided under Public Domain Mark 1.0 may be copied, modified, distributed and performed, including for commercial purposes, without asking permission. In-copyright, NoC and CC BY-NC-SA items are withheld.',
    attribution: `Bayerische Staatsbibliothek, München (MDZ), ${recordUrl} (${gate.basis === 'pdm' ? 'Public Domain Mark 1.0' : 'CC0 1.0'})`,
    recordUrl,
    viewerUrl: recordUrl,
    metadataSource: `${METADATA}/${id}`,
    iiifManifest: `${MANIFEST}/${id}/manifest`,
    retrieved: RETRIEVED,
    geoNote:
      'MDZ states a title, publication place/date and often a scale only. No map extent, projection, georeference or alignment is inferred; the IIIF manifest opens the original scan.',
  };
  if (metadata.urn ?? hit.doi) record.urn = metadata.urn ?? hit.doi;
  if (previewId) {
    record.thumbnail = `${IMAGE}/${previewId}/full/280,/0/default.jpg`;
    record.imageService = `${IMAGE}/${previewId}`;
  }
  if (metadata.publishedDate) record.dateDisplay = plain(metadata.publishedDate);
  if (years) {
    record.yearStart = years.start;
    record.yearEnd = years.end;
  }
  if (places.length) record.place = places.join(' ; ');
  if ((metadata.publishedBy ?? []).length) record.imprint = unique(metadata.publishedBy).join(' ; ');
  if (languages.length) record.languages = languages;
  if ((metadata.subjects ?? []).length) record.subjects = unique(metadata.subjects).slice(0, 24);
  if (metadata.extent) record.physicalExtent = plain(metadata.extent);
  if (metadata.scale) record.scale = plain(metadata.scale);
  if (metadata.dimensions) record.dimensions = plain(metadata.dimensions);
  if (metadata.shelfNumber ?? metadata.shelfGroups) record.shelfmark = plain(metadata.shelfNumber ?? (metadata.shelfGroups ?? []).join(' ; '));
  if (metadata.byline) record.byline = plain(metadata.byline);
  if (metadata.scanDate) record.sourceModified = metadata.scanDate;
  for (const key of Object.keys(record)) {
    const v = record[key];
    if (key === 'creators') continue;
    if (v == null || v === '' || (Array.isArray(v) && v.length === 0)) delete record[key];
  }
  record.creators ??= [];
  return { record };
}

function searchUrl(page) {
  const url = new URL(SEARCH);
  url.searchParams.set('query', '*');
  url.searchParams.set('handler', 'simple-all');
  url.searchParams.set('pageSize', String(PAGE_SIZE));
  url.searchParams.set('startPage', String(page));
  url.searchParams.set('sortField', 'title');
  url.searchParams.set('sortOrder', 'ASC');
  url.searchParams.append('filter', `collections:${COLLECTION_ID}`);
  return url.toString();
}

async function cachedJson(url, key, { attempts = 4 } = {}) {
  const file = resolve(CACHE, `${key}.json`);
  if (!REFRESH) {
    try {
      return JSON.parse(await readFile(file, 'utf8'));
    } catch {}
  }
  let last;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const res = await fetch(url, { headers: { accept: 'application/json', 'user-agent': UA } });
      if (res.ok) {
        const body = await res.text();
        const parsed = JSON.parse(body);
        await mkdir(dirname(file), { recursive: true });
        await writeFile(file, body);
        return parsed;
      }
      last = new Error(`${res.status} ${url}`);
      if (res.status !== 429 && res.status < 500) break;
    } catch (error) {
      last = error;
    }
    await sleep(700 * attempt);
  }
  throw last;
}

async function pooled(items, worker, concurrency = CONCURRENCY) {
  const results = new Array(items.length);
  let cursor = 0;
  const runners = Array.from({ length: Math.min(concurrency, items.length) }, async () => {
    while (true) {
      const index = cursor++;
      if (index >= items.length) return;
      results[index] = await worker(items[index], index);
      await sleep(40);
    }
  });
  await Promise.all(runners);
  return results;
}

async function verify(records) {
  const sample = [];
  const step = Math.max(1, Math.floor(records.length / Math.max(1, VERIFY_SAMPLE)));
  for (let i = 0; i < records.length && sample.length < VERIFY_SAMPLE; i += step) sample.push(records[i]);
  const results = [];
  for (const record of sample) {
    const result = { id: record.id, manifest: null, thumbnail: null, recordPage: null };
    try {
      const res = await fetch(record.iiifManifest, {
        headers: { accept: 'application/json', 'user-agent': UA },
        signal: AbortSignal.timeout(25000),
      });
      const manifest = JSON.parse(await res.text());
      result.manifest = { status: res.status, contentType: res.headers.get('content-type'), license: manifest.license };
    } catch (error) {
      result.manifest = { error: String(error?.message || error) };
    }
    if (record.thumbnail) {
      try {
        const res = await fetch(record.thumbnail, {
          headers: { 'user-agent': UA },
          signal: AbortSignal.timeout(25000),
        });
        const bytes = new Uint8Array(await res.arrayBuffer());
        result.thumbnail = {
          status: res.status,
          contentType: res.headers.get('content-type'),
          bytes: bytes.length,
          jpeg: bytes[0] === 0xff && bytes[1] === 0xd8,
        };
      } catch (error) {
        result.thumbnail = { error: String(error?.message || error) };
      }
    }
    try {
      const res = await fetch(record.recordUrl, {
        headers: { accept: 'text/html', 'user-agent': UA },
        signal: AbortSignal.timeout(25000),
      });
      result.recordPage = { status: res.status, contentType: res.headers.get('content-type') };
    } catch (error) {
      result.recordPage = { error: String(error?.message || error) };
    }
    results.push(result);
    await sleep(150);
  }
  return results;
}

async function main() {
  const searchHits = new Map();
  let pagesRead = 0;
  let numTotal = null;
  for (let page = 0; ; page++) {
    const response = await cachedJson(searchUrl(page), `search-${String(page).padStart(3, '0')}`);
    numTotal ??= response?.numTotal ?? null;
    const docs = response?.docs ?? [];
    if (!docs.length) break;
    pagesRead += 1;
    for (const doc of docs) if (doc?.id) searchHits.set(doc.id, doc);
    const totalPages = Math.ceil((response?.numTotal ?? 0) / PAGE_SIZE);
    if (page + 1 >= totalPages) break;
    await sleep(100);
  }
  console.log(`Search: ${numTotal} catalogue hits, ${searchHits.size} unique ids in ${pagesRead} pages.`);

  const ids = [...searchHits.keys()];
  const withheld = new Map();
  const metadataResults = await pooled(ids, async (id) => {
    try {
      return { id, metadata: await cachedJson(`${METADATA}/${id}`, `meta-${id}`) };
    } catch (error) {
      return { id, error: String(error?.message || error) };
    }
  });
  const records = [];
  const seen = new Set();
  const seenUrns = new Set();
  let considered = 0;
  for (const { id, metadata, error } of metadataResults) {
    considered += 1;
    if (error) {
      withheld.set('metadata-error', (withheld.get('metadata-error') ?? 0) + 1);
      continue;
    }
    const { record, reason } = mdzRecord(metadata, searchHits.get(id));
    if (!record) {
      withheld.set(reason, (withheld.get(reason) ?? 0) + 1);
      continue;
    }
    if (seen.has(record.id)) continue;
    if (record.urn && seenUrns.has(record.urn)) {
      withheld.set('duplicate-urn', (withheld.get('duplicate-urn') ?? 0) + 1);
      continue;
    }
    seen.add(record.id);
    if (record.urn) seenUrns.add(record.urn);
    records.push(record);
  }
  records.sort((a, b) => a.id.localeCompare(b.id));
  const withheldCounts = Object.fromEntries([...withheld.entries()].sort());
  console.log({ considered, kept: records.length, withheld: withheldCounts });
  const verification = VERIFY_SAMPLE ? await verify(records) : [];
  if (verification.length) console.log('Verification:', verification);

  const generatedAt = new Date().toISOString();
  const method =
    'Bavarian State Library / MDZ "Karten und Pläne / Maps and Plans" catalogue collection via the official MDZ JSON search endpoint, with item-level MDZ metadata licence gate (Public Domain Mark 1.0 / CC0 only), IIIF Presentation API 2 manifests and Image API 2 links, published as a catalogue shard.';
  const selection = {
    source: 'Bayerische Staatsbibliothek — MDZ (Münchner DigitalisierungsZentrum)',
    endpoint: searchUrl(0),
    collection: { id: COLLECTION_ID, name: COLLECTION_NAME },
    documentation: 'https://www.digitale-sammlungen.de/en/interfaces',
    metadataEndpoint: `${METADATA}/{id}`,
    manifestEndpoint: `${MANIFEST}/{id}/manifest`,
    imageEndpoint: `${IMAGE}/{previewId}`,
    searchApiNote:
      'The /api/search and /api/metadata routes are the official public MDZ catalogue endpoints used by the website; the IIIF Presentation/Image APIs are documented on the MDZ Interfaces page.',
    pagesRead,
    pageTotal: numTotal,
    considered,
    kept: records.length,
    shard: SHARD,
    rightsBasis: 'item-level Public Domain Mark 1.0 or CC0 1.0 only',
    withheld: withheldCounts,
    rule:
      'Every catalogue hit in the MDZ collection 137 ("Karten und Pläne / Maps and Plans") is a candidate. It is imported only when /api/metadata/<id> states iiifAvailable=true and a Public Domain Mark 1.0 or CC0 1.0 licence, the title is non-empty, and the record has a URN or preview image. In-copyright, NoC, CC BY-NC-SA and unstated items are withheld. Titles, creators, dates, places, imprint, language, extent, scale, shelfmark and URN stay verbatim; no map extent, projection or alignment is inferred.',
    metadataReuse: {
      status: 'basis-recorded',
      basis:
        'Only item-level Public Domain Mark 1.0 / CC0 objects are redistributed. The MDZ FAQ states that digital copies under Public Domain Mark 1.0 may be copied, modified, distributed and performed, including for commercial purposes, without asking permission. The redistributed fields are the factual description of that object plus its URN and record link. MDZ publishes no separate metadata licence; none is asserted.',
      primaryEvidence: [
        {
          url: 'https://www.digitale-sammlungen.de/en/faq',
          retrieved: RETRIEVED,
          quote:
            "Digital copies provided under the rights statement 'Public Domain Mark 1.0' may be copied, modified, distributed and performed, including for commercial purposes, without having to ask for permission.",
        },
        {
          url: 'https://www.digitale-sammlungen.de/en/interfaces',
          retrieved: RETRIEVED,
          quote:
            'The APIs (Application Programming Interface) ... When using a digital copy, please note the rights statement under which it is provided.',
        },
      ],
      limits:
        'Applies only to the admitted item-level PDM/CC0 objects. In-copyright, NoC and CC BY-NC-SA items are withheld. Attribution and the record/URN links stay on every record.',
    },
    verification,
    retrieved: RETRIEVED,
  };
  const provider = {
    id: 'mdz',
    name: 'Bavarian State Library — Maps and Plans (MDZ)',
    operator: 'Bayerische Staatsbibliothek (Bavarian State Library)',
    homepage: 'https://www.digitale-sammlungen.de/en/maps-images',
    home: 'https://www.digitale-sammlungen.de/',
    institutions: ['Bayerische Staatsbibliothek, München'],
    rights:
      'Item-level only: MDZ metadata must state iiifAvailable=true and Public Domain Mark 1.0 or CC0 1.0. In-copyright, NoC and CC BY-NC-SA items are withheld; the verbatim licence is retained on each record.',
    attribution: 'Bayerische Staatsbibliothek, München (MDZ)',
    terms: 'https://www.digitale-sammlungen.de/en/faq',
    retrieved: RETRIEVED,
    api: {
      discovery: searchUrl(0),
      documentation: 'https://www.digitale-sammlungen.de/en/interfaces',
      record: `${METADATA}/{id}`,
      manifest: `${MANIFEST}/{id}/manifest`,
      image: `${IMAGE}/{previewId}`,
    },
    apiHosts: ['www.digitale-sammlungen.de', 'api.digitale-sammlungen.de'],
    method,
    collections: [
      {
        id: 'karten-und-plaene',
        name: COLLECTION_NAME,
        discovery: searchUrl(0),
      },
    ],
    verification,
    metadataReuse: selection.metadataReuse,
  };

  const sourcesPath = resolve(OUT, 'sources.json');
  const sources = JSON.parse(await readFile(sourcesPath, 'utf8'));
  sources.providers = [...sources.providers.filter((source) => source.id !== 'mdz'), provider];
  sources.generatedAt = generatedAt;
  const shardBytes = Buffer.byteLength(JSON.stringify({ records }));
  const coreBytes = Buffer.byteLength(JSON.stringify(await readCore(OUT), null, 2));
  console.log(`Shard ${(shardBytes / 1024 / 1024).toFixed(2)} MiB, core ${(coreBytes / 1024 / 1024).toFixed(2)} MiB`);
  if (coreBytes > 24 * 1024 * 1024 || shardBytes > 24 * 1024 * 1024) {
    throw new Error('A catalogue asset exceeds 24 MiB; split it before writing.');
  }
  if (WRITE) {
    const core = await publishProviderShard(OUT, SHARD, 'mdz', records, {
      generatedAt,
      retrieved: RETRIEVED,
      providerId: 'mdz',
      method,
      selection,
    });
    core.generatedAt = generatedAt;
    core.retrieved = RETRIEVED;
    core.method = `${core.method ? `${core.method} ` : ''}${method}`;
    core.selection ??= {};
    core.selection['mdz:karten-und-plaene'] = selection;
    await writeFile(resolve(OUT, 'records.json'), `${JSON.stringify(core, null, 2)}\n`);
    await writeFile(sourcesPath, `${JSON.stringify(sources, null, 2)}\n`);
    console.log('Wrote', resolve(OUT, 'records/mdz.json'), 'and', sourcesPath);
  }
}

if (process.argv[1] && import.meta.url === new URL(`file://${resolve(process.argv[1])}`).href) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
